import {ActorType} from '../types/role-assignments'
import type {AvatarEnterprise, IndirectRoleAssignmentSource, RoleAssignment} from '../types/role-assignments'
import {Token} from '@primer/react'
import type {ComponentPropsWithoutRef} from 'react'
import styles from './RoleAssignmentSources.module.css'
import {clsx} from 'clsx'
import {Fragment} from 'react'
import {RoleAvatarSpread} from './RoleAvatarSpread'
import {AllOrgsTokenComponent} from './AllOrgsTokenComponent'
import {testIdProps} from '@github-ui/test-id-props'
import {isEsm} from '../utils/role-utils'

type SpanProps = ComponentPropsWithoutRef<'span'>
const defaultProps = {} as SpanProps
const defaultAllOrganizationAvatarURLs = [] as string[]

interface RoleAssignmentSourcesProps extends SpanProps {
  roleAssignment: RoleAssignment
  includeAssignedViaPrefix: boolean
  includeDirectSource: boolean
  linkTeams: boolean
  allOrganizationAvatarURLs?: string[]
  directSourceProps?: SpanProps
  teamSourceProps?: SpanProps
  avatarEnterprise?: AvatarEnterprise
}

export function RoleAssignmentSources({
  roleAssignment,
  includeAssignedViaPrefix = false,
  includeDirectSource = false,
  linkTeams = false,
  allOrganizationAvatarURLs = defaultAllOrganizationAvatarURLs,
  directSourceProps = defaultProps,
  teamSourceProps = defaultProps,
  avatarEnterprise,
  ...componentProps
}: RoleAssignmentSourcesProps) {
  const hasDirectAssignment = includeDirectSource && roleAssignment.directly_assigned
  const indirectAssignmentSources = roleAssignment.indirect_assignments
  const enterpriseTeamAssignmentSources = indirectAssignmentSources.filter(
    source => source.type === ActorType.EnterpriseTeam,
  )
  const organizationTeamAssignmentSources = indirectAssignmentSources.filter(source => source.type === ActorType.Team)
  const assignmentCount =
    enterpriseTeamAssignmentSources.length + organizationTeamAssignmentSources.length + (hasDirectAssignment ? 1 : 0)

  if (assignmentCount === 0) return null

  const hasEnterpriseTeamAssignments = enterpriseTeamAssignmentSources.length > 0
  const hasOrganizationTeamAssignments = organizationTeamAssignmentSources.length > 0
  const hasTeamAssignments = hasEnterpriseTeamAssignments || hasOrganizationTeamAssignments

  function assignedViaPrefixElement() {
    if (!includeAssignedViaPrefix) return null

    if (assignmentCount > 1) {
      return <span>Assigned via {assignmentCount} sources: </span>
    } else {
      return <span>Assigned via: </span>
    }
  }

  function directAssignmentElement() {
    if (!hasDirectAssignment) return null

    return (
      <Token
        text="direct assignment"
        className={clsx(styles.sourceToken, directSourceProps.className)}
        {...directSourceProps}
      />
    )
  }

  function teamAssignmentElement(source: IndirectRoleAssignmentSource, index: number) {
    const leadingVisual = () => <RoleAvatarSpread avatarURLs={[source.team_avatar_url]} />

    let element: React.ReactElement
    if (linkTeams) {
      element = (
        <Token
          as="a"
          leadingVisual={leadingVisual}
          href={source.team_url}
          text={source.team_name}
          className={clsx(styles.sourceToken, teamSourceProps.className)}
          {...teamSourceProps}
        />
      )
    } else {
      element = (
        <Token
          leadingVisual={leadingVisual}
          text={source.team_name}
          className={clsx(styles.sourceToken, teamSourceProps.className)}
          {...teamSourceProps}
        />
      )
    }

    const key = `team-assignment-${source.type}-${index}`
    return <Fragment key={key}>{element} </Fragment>
  }

  function enterpriseTeamAssignmentElements() {
    return enterpriseTeamAssignmentSources.map(teamAssignmentElement)
  }

  function organizationTeamAssignmentElements() {
    return organizationTeamAssignmentSources.map(teamAssignmentElement)
  }

  function enterpriseSuffixElement() {
    if (!avatarEnterprise || !isEsm(roleAssignment.role)) return null

    const {displayLogin, avatarURL} = avatarEnterprise

    return (
      <>
        <span> from the </span>
        <Token
          className={styles.sourceToken}
          text={displayLogin}
          leadingVisual={() => <RoleAvatarSpread avatarURLs={[avatarURL]} {...testIdProps('enterprise-token')} />}
        />
        <span> enterprise.</span>
      </>
    )
  }

  function enterpriseTeamSuffixElement() {
    switch (enterpriseTeamAssignmentSources.length) {
      case 0:
        return null
      case 1:
        return <span> enterprise team</span>
      default:
        return <span> enterprise teams</span>
    }
  }

  function organizationTeamSuffixElement() {
    switch (organizationTeamAssignmentSources.length) {
      case 0:
        return null
      case 1:
        return <span> team</span>
      default:
        return <span> teams</span>
    }
  }

  function accessToAllElement() {
    if (roleAssignment.org_access == null) return null

    return (
      <>
        {hasTeamAssignments && <span>,</span>}
        <span> granting access to </span>
        <AllOrgsTokenComponent
          orgAccess={roleAssignment.org_access}
          roleName={roleAssignment.role.name}
          allOrganizationAvatarURLs={allOrganizationAvatarURLs}
        />
      </>
    )
  }

  const connectorElement = (text: string) => {
    return <span> {text} </span>
  }

  return (
    <span {...componentProps}>
      {assignedViaPrefixElement()}
      {directAssignmentElement()}
      {hasDirectAssignment && hasTeamAssignments && connectorElement('and')}
      {enterpriseTeamAssignmentElements()}
      {enterpriseTeamSuffixElement()}
      {enterpriseSuffixElement()}
      {hasEnterpriseTeamAssignments && hasOrganizationTeamAssignments && connectorElement('and')}
      {organizationTeamAssignmentElements()}
      {organizationTeamSuffixElement()}
      {accessToAllElement()}
    </span>
  )
}

try{ RoleAssignmentSources.displayName ||= 'RoleAssignmentSources' } catch {}