import {GitHubAvatar} from '@github-ui/github-avatar'
import {testIdProps} from '@github-ui/test-id-props'

export interface RoleAvatarSpreadProps {
  avatarURLs: string[]
}

export function RoleAvatarSpread({avatarURLs}: RoleAvatarSpreadProps) {
  return (
    <div className="RoleAvatarSpread" {...testIdProps('enterprise-orgs-avatarstack')}>
      {avatarURLs.map(avatarURL => (
        <div className="RoleAvatarSpread-avatar" key={avatarURL}>
          <GitHubAvatar {...testIdProps('enterprise-org-avatar')} src={avatarURL} />
        </div>
      ))}
    </div>
  )
}

try{ RoleAvatarSpread.displayName ||= 'RoleAvatarSpread' } catch {}